155	     3	/**
156	     4	 * The Luhn check digit (0-9) computed over the digits contained in an owner's customer code.
157	     5	 * Non-digit characters (the hyphens) are ignored; the standard Luhn algorithm doubles every
158	     6	 * second digit from the right and reduces the running sum modulo ten.
159	     7	 */
160	     8	public final class CheckDigit {
161	     9	
162	    10	    private CheckDigit() {
163	    11	    }
164	    12	
165	    13	    public static Integer of(String customerCode) {
166	    14	        if (customerCode == null) {
167	    15	            return null;
168	    16	        }
169	    17	        int sum = 0;
170	    18	        boolean dbl = true;
171	    19	        for (int i = customerCode.length() - 1; i >= 0; i--) {
172	    20	            char c = customerCode.charAt(i);
173	    21	            if (c < '0' || c > '9') {
174	    22	                continue;
175	    23	            }
176	    24	            int d = c - '0';
177	    25	            if (dbl) {
178	    26	                d *= 2;
179	    27	                if (d > 9) {
180	    28	                    d -= 9;
181	    29	                }
182	    30	            }
183	    31	            sum += d;
184	    32	            dbl = !dbl;
185	    33	        }
186	    34	        return (10 - (sum % 10)) % 10;
187	    35	    }
188	    36	}
